import{_ as t,a,o,a4 as n}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"CMS Page — Update","description":"","frontmatter":{"outline":false,"examples":[{"id":"admin-cms-pages-update","title":"Update a CMS Page (locale-nested)","description":"Validation is LOCALE-NESTED. Top-level `locale` names which block is being updated.","query":"mutation UpdateCmsPage($input: updateAdminCmsPageInput!) {\\n  updateAdminCmsPage(input: $input) {\\n    adminCmsPage {\\n      id\\n      _id\\n      urlKey\\n      pageTitle\\n      htmlContent\\n      metaTitle\\n      metaKeywords\\n      metaDescription\\n      locale\\n      previewUrl\\n      createdAt\\n      updatedAt\\n      translations {\\n        edges {\\n          node {\\n            locale\\n            urlKey\\n            pageTitle\\n            htmlContent\\n            metaTitle\\n            metaKeywords\\n            metaDescription\\n          }\\n        }\\n      }\\n      channels {\\n        edges {\\n          node {\\n            _id\\n            code\\n            name\\n          }\\n        }\\n      }\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"id\\": \\"/api/admin/cms/pages/7\\",\\n    \\"locale\\": \\"en\\",\\n    \\"channels\\": [1],\\n    \\"en\\": {\\n      \\"url_key\\": \\"about-us\\",\\n      \\"page_title\\": \\"About Us (Updated)\\",\\n      \\"html_content\\": \\"<h1>About Us</h1>\\",\\n      \\"meta_title\\": \\"About Us\\",\\n      \\"meta_keywords\\": \\"about,us,company\\",\\n      \\"meta_description\\": \\"Learn more about our company.\\"\\n    }\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"updateAdminCmsPage\\": {\\n      \\"adminCmsPage\\": {\\n        \\"id\\": \\"/api/admin/cms/pages/7\\",\\n        \\"_id\\": 7,\\n        \\"urlKey\\": \\"about-us\\",\\n        \\"pageTitle\\": \\"About Us (Updated)\\",\\n        \\"htmlContent\\": \\"<h1>About Us</h1>\\",\\n        \\"metaTitle\\": \\"About Us\\",\\n        \\"metaKeywords\\": \\"about,us,company\\",\\n        \\"metaDescription\\": \\"Learn more about our company.\\",\\n        \\"locale\\": \\"en\\",\\n        \\"previewUrl\\": \\"https://store.example.com/page/about-us\\",\\n        \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n        \\"updatedAt\\": \\"2026-06-23T11:49:19+00:00\\",\\n        \\"translations\\": {\\n          \\"edges\\": [\\n            {\\n              \\"node\\": {\\n                \\"locale\\": \\"en\\",\\n                \\"urlKey\\": \\"about-us\\",\\n                \\"pageTitle\\": \\"About Us (Updated)\\",\\n                \\"htmlContent\\": \\"<h1>About Us</h1>\\",\\n                \\"metaTitle\\": \\"About Us\\",\\n                \\"metaKeywords\\": \\"about,us,company\\",\\n                \\"metaDescription\\": \\"Learn more about our company.\\"\\n              }\\n            }\\n          ]\\n        },\\n        \\"channels\\": {\\n          \\"edges\\": [\\n            { \\"node\\": { \\"_id\\": 1, \\"code\\": \\"default\\", \\"name\\": \\"Default\\" } }\\n          ]\\n        }\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/cms/pages/mutations/update.md","filePath":"api/graphql-api/admin/cms/pages/mutations/update.md","lastUpdated":1783420618000}'),d={name:"api/graphql-api/admin/cms/pages/mutations/update.md"};function r(c,e,s,i,l,p){return o(),a("div",null,e[0]||(e[0]=[n('<h1 id="cms-page-—-update" tabindex="-1">CMS Page — Update <a class="header-anchor" href="#cms-page-—-update" aria-label="Permalink to &quot;CMS Page — Update&quot;">​</a></h1><p>Edits <strong>one locale</strong> of an existing CMS page. Equivalent to <a href="/api/rest-api/admin/cms/pages-update.html"><code>PUT /api/admin/cms/pages/{id}</code></a>.</p><div class="tip custom-block"><p class="custom-block-title">Prerequisites</p><p>The example uses an illustrative <code>id</code> value. Replace it with the id of a CMS page that exists in your store — use the <a href="/api/graphql-api/admin/cms/pages/queries/list.html"><code>adminCmsPages</code></a> query to discover valid ids.</p></div><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th></tr></thead><tbody><tr><td><code>updateAdminCmsPage</code></td><td>Mutation</td></tr></tbody></table><h2 id="input" tabindex="-1">Input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;Input&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td><code>ID!</code></td><td>yes</td><td>Resource IRI — <code>/api/admin/cms/pages/{id}</code>.</td></tr><tr><td><code>locale</code></td><td><code>String!</code></td><td>yes</td><td>Which locale block is being written. Only this locale&#39;s content changes; other locales are left untouched.</td></tr><tr><td><code>channels</code></td><td><code>[Int!]!</code></td><td>yes</td><td>Non-empty list of channel IDs. <strong>Replaces</strong> the page&#39;s current channel assignment.</td></tr><tr><td><code>&lt;locale&gt;</code></td><td><code>Object</code></td><td>yes</td><td>A block keyed by the <code>locale</code> value above — <code>{ url_key, page_title, html_content, meta_title, meta_keywords, meta_description }</code>. <code>url_key</code>, <code>page_title</code>, and <code>html_content</code> are required inside it.</td></tr></tbody></table><h2 id="locale-nested-payload" tabindex="-1">Locale-nested payload <a class="header-anchor" href="#locale-nested-payload" aria-label="Permalink to &quot;Locale-nested payload&quot;">​</a></h2><p>Update is <strong>per-locale</strong>, mirroring the admin edit form. The top-level <code>locale</code> names which language you are editing, and the matching block (e.g. <code>en: { … }</code>) carries that locale&#39;s content. To update a second language, send another request with <code>locale: &quot;fr&quot;</code> and an <code>fr: { … }</code> block. The block name <strong>must</strong> equal the <code>locale</code> value — <code>locale: &quot;en&quot;</code> requires an <code>en</code> block.</p><p>This differs from <a href="/api/graphql-api/admin/cms/pages/mutations/create.html">Create</a>, which takes flat top-level fields broadcast to every locale.</p><h2 id="changing-url-key-creates-a-redirect" tabindex="-1">Changing <code>url_key</code> creates a redirect <a class="header-anchor" href="#changing-url-key-creates-a-redirect" aria-label="Permalink to &quot;Changing `url_key` creates a redirect&quot;">​</a></h2><p>When you change a locale&#39;s <code>url_key</code>, the store automatically records a <strong>301 redirect</strong> from the old slug to the new one, so existing links and bookmarks keep working. Deleting the page later removes those redirects.</p><h2 id="response" tabindex="-1">Response <a class="header-anchor" href="#response" aria-label="Permalink to &quot;Response&quot;">​</a></h2><p>The mutation returns the <strong>updated page</strong>. Every scalar resolves — <code>urlKey</code>, <code>pageTitle</code>, <code>htmlContent</code>, <code>metaTitle</code>, <code>metaKeywords</code>, <code>metaDescription</code>, <code>locale</code>, <code>previewUrl</code>, <code>createdAt</code>, <code>updatedAt</code> — and <code>translations</code> / <code>channels</code> are <strong>field-selectable connections</strong> (<code>{ edges { node { … } } }</code>) reflecting the post-update state. Select only what you need.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Condition</th><th>Result</th></tr></thead><tbody><tr><td><code>url_key</code>, <code>page_title</code>, or <code>html_content</code> missing in the locale block</td><td>validation error</td></tr><tr><td><code>url_key</code> already used by another page</td><td>validation error</td></tr><tr><td><code>channels</code> empty or contains an unknown ID</td><td>validation error</td></tr><tr><td>Page ID not found</td><td>not-found error</td></tr><tr><td>Admin role lacks <code>cms.edit</code></td><td>permission error</td></tr></tbody></table>',16)]))}const m=t(d,[["render",r]]);export{h as __pageData,m as default};
